#include <iostream>

enum class direction { left, right };  // Scoped enum with default underlying type (int)
enum class altitude { high = 'h', low = 'l' };  // Scoped enum with char underlying type implied by initializer

int main() {
    direction d;  // Declaration: 'd' is of type 'direction', not implicitly convertible to int
    d = direction::left;  // OK: Qualified access; compiler resolves this to an integer constant at compile-time
    // d = left;  // Compile-time error: 'left' is not in global scope; strong typing prevents unqualified use

    altitude alt = altitude::high;  // OK: Assigns the char value 'h' to 'alt'
    // int value = static_cast<int>(d);  // Would require explicit cast if needed, but d is not direction
    std::cout << static_cast<char>(alt) << std::endl;  // Runtime output: 'h' (after explicit cast)
    return 0;
}
